  const result = statement('C-001', [issued1, issued2], '2026-10-31');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 1);
  assert.equal(result.value.invoices[0].number, 'INV-2026-0001');
});

test('statement returns empty invoices list when no matching invoices', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  }).value;
